type playerWhere[Q psql.Filterable] struct {
	cols        playerColumns
	ID          psql.WhereMod[Q, int64]
	UUID        psql.WhereMod[Q, uuid.UUID]
	Name        psql.WhereMod[Q, string]
	FirstSeenAt psql.WhereMod[Q, time.Time]
	LastSeenAt  psql.WhereMod[Q, time.Time]
	R           playerWhereR[Q]
}

func (playerWhere[Q]) AliasedAs(alias string) playerWhere[Q] {
	return buildPlayerWhere[Q](buildPlayerColumns(alias))
}

func buildPlayerWhere[Q psql.Filterable](cols playerColumns) playerWhere[Q] {
	return playerWhere[Q]{
		cols:        cols,
		ID:          psql.Where[Q, int64](cols.ID.Expression),
		UUID:        psql.Where[Q, uuid.UUID](cols.UUID.Expression),
		Name:        psql.Where[Q, string](cols.Name.Expression),
		FirstSeenAt: psql.Where[Q, time.Time](cols.FirstSeenAt.Expression),
		LastSeenAt:  psql.Where[Q, time.Time](cols.LastSeenAt.Expression),
		R:           playerWhereR[Q]{cols: cols},
	}
}

// playerWhereR holds the relationship-based filters of
// playerWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type playerWhereR[Q psql.Filterable] struct {
	cols playerColumns
}

// HasMatchPlayers filters parents that have a matching MatchPlayers using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to MatchPlayers).
func (w playerWhereR[Q]) HasMatchPlayers(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(MatchPlayers.NameExpr()),
		sm.Where(MatchPlayers.Columns.PlayerID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

