// NULL-tolerant scan buffer for playerScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type playerPreloadBuf struct {
	ID          null.Val[int64]
	UUID        null.Val[uuid.UUID]
	Name        null.Val[string]
	FirstSeenAt null.Val[time.Time]
	LastSeenAt  null.Val[time.Time]
}

// playerScanMapperNullable maps the preloaded player
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func playerScanMapperNullable(prefix string) scan.Mapper[*Player] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Player, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *playerPreloadBuf) any
		}
		targets := make([]target, 0, 5)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *playerPreloadBuf) any { return &b.ID }})
			case "uuid":
				targets = append(targets, target{i, func(b *playerPreloadBuf) any { return &b.UUID }})
			case "name":
				targets = append(targets, target{i, func(b *playerPreloadBuf) any { return &b.Name }})
			case "first_seen_at":
				targets = append(targets, target{i, func(b *playerPreloadBuf) any { return &b.FirstSeenAt }})
			case "last_seen_at":
				targets = append(targets, target{i, func(b *playerPreloadBuf) any { return &b.LastSeenAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(playerPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Player, error) {
				buf := link.(*playerPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.UUID.IsValue()) &&
					!(buf.Name.IsValue()) &&
					!(buf.FirstSeenAt.IsValue()) &&
					!(buf.LastSeenAt.IsValue()) {
					return nil, nil
				}

				o := new(Player)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.UUID.IsValue() {
					o.UUID = buf.UUID.MustGet()
				}
				if buf.Name.IsValue() {
					o.Name = buf.Name.MustGet()
				}
				if buf.FirstSeenAt.IsValue() {
					o.FirstSeenAt = buf.FirstSeenAt.MustGet()
				}
				if buf.LastSeenAt.IsValue() {
					o.LastSeenAt = buf.LastSeenAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *Player) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "MatchPlayers":
		rels, ok := retrieved.(MatchPlayerSlice)
		if !ok {
			return fmt.Errorf("player cannot load %T as %q", retrieved, name)
		}

		o.R.MatchPlayers = rels
		o.R.Loaded.MatchPlayers = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Player = o
				rel.R.Loaded.Player = true
			}
		}
		return nil
	case "PlayerGameStats":
		rels, ok := retrieved.(PlayerGameStatSlice)
		if !ok {
			return fmt.Errorf("player cannot load %T as %q", retrieved, name)
		}

		o.R.PlayerGameStats = rels
		o.R.Loaded.PlayerGameStats = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Player = o
				rel.R.Loaded.Player = true
			}
		}
		return nil
	case "PlayerMinigameStats":
		rels, ok := retrieved.(PlayerMinigameStatSlice)
		if !ok {
			return fmt.Errorf("player cannot load %T as %q", retrieved, name)
		}

		o.R.PlayerMinigameStats = rels
		o.R.Loaded.PlayerMinigameStats = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Player = o
				rel.R.Loaded.Player = true
			}
		}
		return nil
	case "RoundPlayers":
		rels, ok := retrieved.(RoundPlayerSlice)
		if !ok {
			return fmt.Errorf("player cannot load %T as %q", retrieved, name)
		}

		o.R.RoundPlayers = rels
		o.R.Loaded.RoundPlayers = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Player = o
				rel.R.Loaded.Player = true
			}
		}
		return nil
	case "StatRecords":
		rels, ok := retrieved.(StatRecordSlice)
		if !ok {
			return fmt.Errorf("player cannot load %T as %q", retrieved, name)
		}

		o.R.StatRecords = rels
		o.R.Loaded.StatRecords = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Player = o
				rel.R.Loaded.Player = true
			}
		}
		return nil
	case "StatValues":
		rels, ok := retrieved.(StatValueSlice)
		if !ok {
			return fmt.Errorf("player cannot load %T as %q", retrieved, name)
		}

		o.R.StatValues = rels
		o.R.Loaded.StatValues = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Player = o
				rel.R.Loaded.Player = true
			}
		}
		return nil
	default:
		return fmt.Errorf("player has no relationship %q", name)
	}
}

