// LoadMatchPlayers loads the player's MatchPlayers into the .R struct
func (o *Player) LoadMatchPlayers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.MatchPlayers = nil
	o.R.Loaded.MatchPlayers = false

	related, err := o.MatchPlayers(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Player = o
		rel.R.Loaded.Player = true
	}

	o.R.MatchPlayers = related
	o.R.Loaded.MatchPlayers = true
	return nil
}

// LoadMatchPlayers loads the player's MatchPlayers into the .R struct
func (os PlayerSlice) LoadMatchPlayers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	matchPlayers, err := os.MatchPlayers(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.MatchPlayers = nil
		o.R.Loaded.MatchPlayers = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	playerByKey := make(map[int64][]*Player, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		playerByKey[o.ID] = append(playerByKey[o.ID], o)
	}

	for _, rel := range matchPlayers {

		owners, ok := playerByKey[rel.PlayerID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Player = o
			rel.R.Loaded.Player = true

			o.R.MatchPlayers = append(o.R.MatchPlayers, rel)

		}
	}

	return nil
}

