// playerC is where relationship counts are stored.
type playerC struct {
	MatchPlayers        *int64
	PlayerGameStats     *int64
	PlayerMinigameStats *int64
	RoundPlayers        *int64
	StatRecords         *int64
	StatValues          *int64
}

// PreloadCount sets a count in the C struct by name
func (o *Player) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "MatchPlayers":
		o.C.MatchPlayers = &count
	case "PlayerGameStats":
		o.C.PlayerGameStats = &count
	case "PlayerMinigameStats":
		o.C.PlayerMinigameStats = &count
	case "RoundPlayers":
		o.C.RoundPlayers = &count
	case "StatRecords":
		o.C.StatRecords = &count
	case "StatValues":
		o.C.StatValues = &count
	}
	return nil
}

