type playerJoins[Q dialect.Joinable] struct {
	typ                 string
	MatchPlayers        modAs[Q, matchPlayerColumns]
	PlayerGameStats     modAs[Q, playerGameStatColumns]
	PlayerMinigameStats modAs[Q, playerMinigameStatColumns]
	RoundPlayers        modAs[Q, roundPlayerColumns]
	StatRecords         modAs[Q, statRecordColumns]
	StatValues          modAs[Q, statValueColumns]
}

func (j playerJoins[Q]) aliasedAs(alias string) playerJoins[Q] {
	return buildPlayerJoins[Q](buildPlayerColumns(alias), j.typ)
}

func buildPlayerJoins[Q dialect.Joinable](cols playerColumns, typ string) playerJoins[Q] {
	return playerJoins[Q]{
		typ: typ,
		MatchPlayers: modAs[Q, matchPlayerColumns]{
			c: MatchPlayers.Columns,
			f: func(to matchPlayerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, MatchPlayers.NameExpr().As(to.Alias())).On(
						to.PlayerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		PlayerGameStats: modAs[Q, playerGameStatColumns]{
			c: PlayerGameStats.Columns,
			f: func(to playerGameStatColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PlayerGameStats.NameExpr().As(to.Alias())).On(
						to.PlayerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		PlayerMinigameStats: modAs[Q, playerMinigameStatColumns]{
			c: PlayerMinigameStats.Columns,
			f: func(to playerMinigameStatColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PlayerMinigameStats.NameExpr().As(to.Alias())).On(
						to.PlayerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		RoundPlayers: modAs[Q, roundPlayerColumns]{
			c: RoundPlayers.Columns,
			f: func(to roundPlayerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RoundPlayers.NameExpr().As(to.Alias())).On(
						to.PlayerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		StatRecords: modAs[Q, statRecordColumns]{
			c: StatRecords.Columns,
			f: func(to statRecordColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, StatRecords.NameExpr().As(to.Alias())).On(
						to.PlayerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		StatValues: modAs[Q, statValueColumns]{
			c: StatValues.Columns,
			f: func(to statValueColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, StatValues.NameExpr().As(to.Alias())).On(
						to.PlayerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
